-- A database built by the v1 Ledger (tag v1-final): a counts-only 2025 ghost, the live Rehearsal racing it
-- with tags, taps, a teen, a removed kid, a catch-up, a backfill batch, golden tickets, a fired
-- milestone, an ended night and the TV mix, plus a spare not-yet-live event. Opened by the v2 migration tests.
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE events (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    live INTEGER NOT NULL DEFAULT 0,
    frozen INTEGER NOT NULL DEFAULT 0,
    ended INTEGER NOT NULL DEFAULT 0,
    join_key TEXT,
    clock_shift_ms INTEGER NOT NULL DEFAULT 0,
    race_against_id INTEGER REFERENCES events(id),
    expected_kids INTEGER,
    visit_window_ms INTEGER NOT NULL DEFAULT 15000,
    golden_count INTEGER NOT NULL DEFAULT 0,
    counts_only INTEGER NOT NULL DEFAULT 0
  );
CREATE TABLE ghost_buckets (
    event_id INTEGER NOT NULL REFERENCES events(id),
    slot_start TEXT NOT NULL,
    slot_end TEXT NOT NULL,
    count INTEGER NOT NULL
  );
CREATE TABLE tags (
    id INTEGER PRIMARY KEY,
    event_id INTEGER NOT NULL REFERENCES events(id),
    name TEXT NOT NULL,
    emoji TEXT,
    sort_order INTEGER NOT NULL,
    sound TEXT
  );
CREATE TABLE kids (
    id TEXT PRIMARY KEY,
    event_id INTEGER NOT NULL REFERENCES events(id),
    number INTEGER NOT NULL,
    tag_id INTEGER REFERENCES tags(id),
    phone_name TEXT,
    tapped_at INTEGER NOT NULL,
    received_at INTEGER NOT NULL,
    late INTEGER NOT NULL DEFAULT 0,
    golden INTEGER NOT NULL DEFAULT 0,
    teen INTEGER NOT NULL DEFAULT 0,
    deleted_at INTEGER,
    source TEXT NOT NULL DEFAULT 'tap',
    backfill_batch_id INTEGER
  );
CREATE TABLE golden_tickets (
    id INTEGER PRIMARY KEY,
    event_id INTEGER NOT NULL REFERENCES events(id),
    number INTEGER NOT NULL,
    state TEXT NOT NULL,
    kid_id TEXT,
    expired_from TEXT
  );
CREATE TABLE backfill_batches (
    id INTEGER PRIMARY KEY,
    event_id INTEGER NOT NULL REFERENCES events(id),
    rows TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    removed_at INTEGER
  );
CREATE TABLE kv (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
  );
CREATE TABLE fired_moments (
    event_id INTEGER NOT NULL REFERENCES events(id),
    moment TEXT NOT NULL,
    state TEXT NOT NULL,
    kid_id TEXT,
    at INTEGER NOT NULL,
    PRIMARY KEY (event_id, moment)
  );
COMMIT;
